import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [open, setOpne] = useState(false);
  const linkNames = [
    { name: "Home", url: "/" },
    { name: "Planets", url: "/planets" },
  ];
  return (
    <div className=" bg-white w-full sm:h-16 md:flex md:justify-around text-black p-5">
      <h1 className=" uppercase font-poppins text-2xl">solar explore</h1>
      <ul className=" md:flex ">
        {linkNames.map((item) => {
         return <li><Link  className=" md:me-10"  to={item.url}>
         {item.name}
       </Link></li>;
        })}
      </ul>
    </div>
  );
}

export default NavBar;
